"""Validaciones de reservas.

validar_sala() y validar_horario() son independientes entre sí.
"""
from datetime import datetime, timedelta

from app.config import SALAS


class ValidationError(Exception):
    pass


def validar_sala(sala: str) -> None:
    if not sala:
        raise ValidationError("La sala es obligatoria.")
    if sala not in SALAS:
        salas_disponibles = ", ".join(SALAS)
        raise ValidationError(
            f"La sala «{sala}» no existe. Salas disponibles: {salas_disponibles}."
        )


# --- Parámetros de reserva -------------------------------------------------

DURACION_MAXIMA_MIN = 240
MINUTOS_PERMITIDOS = (0, 30)
HORA_APERTURA = 8
HORA_CIERRE = 20


def _es_duracion_valida(duracion_min: int) -> bool:
    return 0 < duracion_min <= DURACION_MAXIMA_MIN


# ---------------------------------------------------------------------------


def validar_horario(fecha: datetime, duracion_min: int) -> None:
    if not _es_duracion_valida(duracion_min):
        raise ValidationError("duracion invalida")
    if fecha.minute not in MINUTOS_PERMITIDOS or fecha.second or fecha.microsecond:
        raise ValidationError("minutos invalidos")
    apertura = fecha.replace(hour=HORA_APERTURA, minute=0, second=0, microsecond=0)
    cierre = fecha.replace(hour=HORA_CIERRE, minute=0, second=0, microsecond=0)
    fin = fecha + timedelta(minutes=duracion_min)
    if fecha < apertura or fin > cierre:
        raise ValidationError("fuera de horario (8:00-20:00)")

"""Consulta pública de reservas."""
from datetime import date

from fastapi import APIRouter

from app import db
from app.consultas import listar_reservas_desde
from app.models import Reserva

router = APIRouter()


@router.get("/reservas")
def listar_reservas(desde: date | None = None) -> list[Reserva]:
    if desde is None:
        return db.listar_reservas()
    return listar_reservas_desde(desde)

from fastapi import APIRouter, Depends, Header, HTTPException

from app import db
from app.auth import Session, get_session
from app.models import Reserva, ReservaIn
from app.validators import ValidationError, validar_horario, validar_sala

router = APIRouter()


def sesion_actual(authorization: str | None = Header(default=None)) -> Session:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="no autenticado")
    session = get_session(authorization.removeprefix("Bearer "))
    if session is None:
        raise HTTPException(status_code=401, detail="sesion invalida")
    return session


@router.post("/reservas", status_code=201)
def crear_reserva(r: ReservaIn, session: Session = Depends(sesion_actual)) -> Reserva:
    try:
        validar_sala(r.sala)
        validar_horario(r.inicio, r.duracion_min)
    except ValidationError as e:
        raise HTTPException(status_code=422, detail=str(e))
    return db.insertar_reserva(r, session.username)

import re
from datetime import datetime

import pytest

from app.validators import ValidationError, validar_horario, validar_sala


def test_sala_valida():
    validar_sala("Boreal")


@pytest.mark.parametrize(
    "sala,mensaje",
    [
        ("", "La sala es obligatoria."),
        ("Delta", "La sala «Delta» no existe. Salas disponibles: Atlas, Boreal, Cierzo."),
    ],
)
def test_sala_errores(sala, mensaje):
    with pytest.raises(ValidationError, match=f"^{re.escape(mensaje)}$"):
        validar_sala(sala)


def test_horario_valido():
    validar_horario(datetime(2026, 10, 5, 9, 30), 90)


@pytest.mark.parametrize("duracion", [0, -30, 241])
def test_horario_duracion_invalida(duracion):
    with pytest.raises(ValidationError, match="^duracion invalida$"):
        validar_horario(datetime(2026, 10, 5, 9, 0), duracion)


def test_horario_minutos_invalidos():
    with pytest.raises(ValidationError, match="^minutos invalidos$"):
        validar_horario(datetime(2026, 10, 5, 9, 15), 60)


def test_horario_limites_validos():
    validar_horario(datetime(2026, 10, 5, 8, 0), 60)
    validar_horario(datetime(2026, 10, 5, 19, 0), 60)


@pytest.mark.parametrize(
    "hora,minuto,duracion",
    [(7, 30, 60), (19, 30, 60)],
)
def test_horario_fuera_de_franja(hora, minuto, duracion):
    with pytest.raises(ValidationError, match=r"^fuera de horario \(8:00-20:00\)$"):
        validar_horario(datetime(2026, 10, 5, hora, minuto), duracion)
